'use strict';

// MODULES //

var hypotf = require( '@stdlib/math-base-special-hypotf' );
var f32 = require( '@stdlib/number-float64-base-to-float32' );


// MAIN //

/**
* Evaluates the signum function of a single-precision complex floating-point number and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* var Float32Array = require( '@stdlib/array-float32' );
*
* var out = assign( 3.0, -4.0, new Float32Array( 2 ), 1, 0 );
* // returns <Float32Array>[ ~0.6, ~-0.8 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	var az;

	az = hypotf( re, im );
	if ( az === 0.0 ) {
		out[ offsetOut ] = re;
		out[ offsetOut+strideOut ] = im;
		return out;
	}
	out[ offsetOut ] = f32( re / az );
	out[ offsetOut+strideOut ] = f32( im / az );
	return out;
}


// EXPORTS //

module.exports = assign;
